import os, json, re
import numpy as np

N = 26
SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'

P_BOUND = 'storage/prometheus/exports_for_noesis/sota_620_boundary_tol_2e8.json'
P_K25   = 'storage/prometheus/exports_for_noesis/sota_620_top_k_slack_1e9.json'
P_K15   = 'storage/prometheus/exports_for_noesis/sota_620_top_k_slack_1e8.json'
OUT_JSON = 'storage/noesis/nmap/prometheus_620_sets_compare.json'

def load_snapshot():
    c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
    r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
    return c, r

def norm_side(s):
    if s is None: return None
    t = re.sub(r'[^a-zA-Z]', '', str(s).strip()).lower()
    if t in ('xl','xmin','xleft','left','l'):  return 'xL'
    if t in ('xr','xmax','xright','right','r'): return 'xR'
    if t in ('yb','ymin','ybottom','bottom','b'): return 'yB'
    if t in ('yt','ymax','ytop','top','t'):      return 'yT'
    if t.startswith('x') and ('min' in t or 'left' in t): return 'xL'
    if t.startswith('x') and ('max' in t or 'right' in t): return 'xR'
    if t.startswith('y') and ('min' in t or 'bottom' in t): return 'yB'
    if t.startswith('y') and ('max' in t or 'top' in t):    return 'yT'
    return None

def read_boundary_json(path):
    S = set(); meta = {'exists': os.path.exists(path)}
    if not meta['exists']: return S, meta
    data = json.load(open(path,'r'))
    # Expected format: {"boundary_equalities":[{"disc":i,"side":"xL"},...]} or list directly
    items = data.get('boundary_equalities', data)
    if isinstance(items, dict): items = items.get('boundary_equalities', [])
    for it in items:
        if isinstance(it, dict):
            i = it.get('disc', it.get('i', it.get('index')))
            s = it.get('side')
            try: i = int(i)
            except Exception: continue
            s = norm_side(s)
            if s is None: continue
            if 0 <= i < N: S.add((i, s))
        elif isinstance(it, (list, tuple)) and len(it) >= 2:
            try:
                i = int(it[0]); s = norm_side(it[1])
            except Exception:
                continue
            if s is None: continue
            if 0 <= i < N: S.add((i, s))
    return S, meta

def read_pairs_json(path):
    S = set(); meta = {'exists': os.path.exists(path), 'parsed': 0}
    if not meta['exists']: return S, meta
    data = json.load(open(path,'r'))
    candidates = []
    # Accept various shapes
    if isinstance(data, dict):
        for k in ('pairs','top_k','topk','data','list'):
            if k in data and isinstance(data[k], (list,tuple)): candidates = data[k]; break
        if not candidates and 'items' in data: candidates = data['items']
        if not candidates and isinstance(data.get('0'), list): candidates = list(data.values())
    elif isinstance(data, list):
        candidates = data
    # Normalize
    for it in candidates:
        i = j = None
        if isinstance(it, dict):
            if 'pair' in it and isinstance(it['pair'], (list,tuple)) and len(it['pair'])>=2:
                i, j = it['pair'][0], it['pair'][1]
            else:
                i = it.get('i', it.get('disc_i', it.get('a')))
                j = it.get('j', it.get('disc_j', it.get('b')))
        elif isinstance(it, (list,tuple)) and len(it)>=2:
            i, j = it[0], it[1]
        try:
            i = int(i); j = int(j)
        except Exception:
            continue
        # Assume 0-based; if min>=1 and max<=N, shift
        if 0 <= i < N and 0 <= j < N:
            S.add((min(i,j), max(i,j))); meta['parsed'] += 1
        elif 1 <= i <= N and 1 <= j <= N:
            i0, j0 = i-1, j-1
            if 0 <= i0 < N and 0 <= j0 < N:
                S.add((min(i0,j0), max(i0,j0))); meta['parsed'] += 1
    return S, meta

def slacks(c, r):
    x = c[:,0]; y = c[:,1]
    s = {'xL': x - r, 'xR': 1 - x - r, 'yB': y - r, 'yT': 1 - y - r}
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    sp = dist - (r[:,None] + r[None,:])
    return s, sp

def boundary_from_snapshot(c, r, tol):
    s, _ = slacks(c, r)
    S = set()
    for i in range(N):
        if s['xL'][i] <= tol + 1e-12: S.add((i,'xL'))
        if s['xR'][i] <= tol + 1e-12: S.add((i,'xR'))
        if s['yB'][i] <= tol + 1e-12: S.add((i,'yB'))
        if s['yT'][i] <= tol + 1e-12: S.add((i,'yT'))
    return S

def topk_pairs_rank_based(sp, K):
    pairs = []
    for i in range(N):
        for j in range(i+1, N):
            pairs.append((float(sp[i,j]), i, j))
    pairs.sort(key=lambda t: t[0])
    return [(i,j) for _,i,j in pairs[:K]]

def jaccard(a, b):
    inter = len(a & b); uni = len(a | b) if (a or b) else 0
    return (inter/uni) if uni>0 else 1.0, inter, uni

# Crossing helpers
def _orient(a,b,c):
    return (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])
def _on_seg(a,b,p):
    return min(a[0],b[0])-1e-18 <= p[0] <= max(a[0],b[0])+1e-18 and min(a[1],b[1])-1e-18 <= p[1] <= max(a[1],b[1])+1e-18
def cross_strict(a,b,c,d):
    o1=_orient(a,b,c); o2=_orient(a,b,d); o3=_orient(c,d,a); o4=_orient(c,d,b)
    return (o1*o2<0) and (o3*o4<0)
def cross_incl(a,b,c,d):
    o1=_orient(a,b,c); o2=_orient(a,b,d); o3=_orient(c,d,a); o4=_orient(c,d,b)
    if (o1*o2<0) and (o3*o4<0): return True
    if abs(o1)<1e-18 and _on_seg(a,b,c): return True
    if abs(o2)<1e-18 and _on_seg(a,b,d): return True
    if abs(o3)<1e-18 and _on_seg(c,d,a): return True
    if abs(o4)<1e-18 and _on_seg(c,d,b): return True
    return False

def disjoint(p,q):
    i,j=p; k,l=q
    return (i!=k) and (i!=l) and (j!=k) and (j!=l)

def construct_packing():
    c, r = load_snapshot()
    s, sp = slacks(c, r)

    # Boundary comparison @ 2e-8
    prom_bound, _ = read_boundary_json(P_BOUND)
    noe_bound_2e8 = boundary_from_snapshot(c, r, tol=2e-8)
    Jb, Ib, Ub = jaccard(prom_bound, noe_bound_2e8)

    # Rank-based Top-K (Noesis) vs Prometheus lists
    top25_noe = set(topk_pairs_rank_based(sp, 25))
    top15_noe = set(topk_pairs_rank_based(sp, 15))
    prom_k25, _ = read_pairs_json(P_K25)
    prom_k15, _ = read_pairs_json(P_K15)

    J25, I25, U25 = jaccard(set(prom_k25), top25_noe)
    J15, I15, U15 = jaccard(set(prom_k15), top15_noe)

    # Interior filter @ 1e-8 (for optional filtered Jaccard)
    bmask_1e8 = np.zeros((N,), bool)
    for i in range(N):
        if (i,'xL') in noe_bound_2e8 or (i,'xR') in noe_bound_2e8 or (i,'yB') in noe_bound_2e8 or (i,'yT') in noe_bound_2e8:
            # still use 1e-8 semantics by recomputing or adopt 2e-8 mask; here we recompute at 1e-8:
            pass
    # Recompute mask exactly at 1e-8
    bmask_1e8 = ( (s['xL'] <= 1e-8+1e-12) | (s['xR'] <= 1e-8+1e-12) | (s['yB'] <= 1e-8+1e-12) | (s['yT'] <= 1e-8+1e-12) )

    def filt_interior(P):
        return set((i,j) for (i,j) in P if (not bmask_1e8[i]) and (not bmask_1e8[j]))

    J25_int, I25_int, U25_int = jaccard(filt_interior(set(prom_k25)), filt_interior(top25_noe))
    J15_int, I15_int, U15_int = jaccard(filt_interior(set(prom_k15)), filt_interior(top15_noe))

    # Gate v1 on Noesis geometry
    inter_dual = set(prom_k25) & set(prom_k15)
    inter_dual_interior = [(i,j) for (i,j) in inter_dual if (not bmask_1e8[i]) and (not bmask_1e8[j])]
    sat_strict = False; sat_incl = False
    coords = c
    for a_idx in range(len(inter_dual_interior)):
        i,j = inter_dual_interior[a_idx]
        A,B = coords[i], coords[j]
        for b_idx in range(a_idx+1, len(inter_dual_interior)):
            k,l = inter_dual_interior[b_idx]
            if not disjoint((i,j),(k,l)):
                continue
            C,D = coords[k], coords[l]
            if cross_strict(A,B,C,D): sat_strict = True
            if cross_incl(A,B,C,D):   sat_incl = True
            if sat_strict and sat_incl: break
        if sat_strict and sat_incl: break

    out = {
        'prometheus_eval': 620,
        'files': {'boundary': P_BOUND, 'k25': P_K25, 'k15': P_K15},
        'boundary_2e8': {
            'prom_count': len(prom_bound),
            'noe_count': len(noe_bound_2e8),
            'intersection': Ib,
            'union': Ub,
            'jaccard': Jb
        },
        'topk_rank_based': {
            'K25@1e-9': {'prom_count': len(prom_k25), 'noe_count': len(top25_noe), 'intersection': I25, 'union': U25, 'jaccard': J25},
            'K15@1e-8': {'prom_count': len(prom_k15), 'noe_count': len(top15_noe), 'intersection': I15, 'union': U15, 'jaccard': J15},
            'interior@1e-8': {
                'K25': {'intersection': I25_int, 'union': U25_int, 'jaccard': J25_int},
                'K15': {'intersection': I15_int, 'union': U15_int, 'jaccard': J15_int}
            }
        },
        'gate_v1_noesis_geometry': {
            'dual_intersection_size': len(inter_dual),
            'dual_interior_size@1e-8': len(inter_dual_interior),
            'sat_strict': bool(sat_strict),
            'sat_inclusive': bool(sat_incl)
        }
    }
    os.makedirs(os.path.dirname(OUT_JSON), exist_ok=True)
    with open(OUT_JSON, 'w') as f: json.dump(out, f, indent=2)
    print('PROM_620_COMPARE_JSON:', OUT_JSON)
    print('BOUNDARY_JACCARD_2e8:', Jb, 'K25_J:', J25, 'K15_J:', J15, 'GATE_STRICT:', sat_strict, 'GATE_INCL:', sat_incl)

    # Return baseline with tiny final shrink
    r_out = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r_out.astype(float)
